select * from mytable limit 5;

-- Write total revenue generated by male and female
select gender, sum(purchase_amount) as revenue from mytable
group by gender;

-- Write customers used discount but still spend more than average purchase amount
select customer_id, purchase_amount from mytable
where discount_applied = 'Yes' and purchase_amount >= (select avg(purchase_amount) from mytable)
;

-- Write top 5 products with highest review rating
select item_purchased, round(avg(review_rating),1) as avg_rating from mytable
group by item_purchased
order by avg_rating desc limit 5;

-- Compare average purchase amount from standard and express shipping
select shipping_type, avg(purchase_amount) from mytable
group by shipping_type;

-- Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers
select subscription_status,count(customer_id), avg(purchase_amount) as avg_spent, sum(purchase_amount) as total_revenue from mytable
group by subscription_status;

-- Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased, count(item_purchased) as no_of_purchases from mytable
where discount_applied = 'Yes'
group by item_purchased
order by no_of_purchases desc limit 5
;

-- Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment

with customer_type as (
select customer_Id, previous_purchases,
 case
 	when previous_purchases = 1 Then 'New'
	when previous_purchases between 2 and 10 then 'Returning'
else 'Loyal'
end as customer_segment
from mytable
)
select customer_segment, count(*) as 'no of customer'
from customer_type
group by customer_segment;

-- What are the top 3 most purchased products within each category?
with item_counts as (
select category,
item_purchased,
count(customer_id) as total_orders,
row_number() over(partition by category order by count(customer_id) desc) as item_rank
from mytable
group by category, item_purchased
)
select item_rank, category, item_purchased, total_orders
from item_counts
where item_rank <=3;

with item_ranks as (
select category, item_purchased, count(customer_id) as total_orders,
row_number() over(partition by category order by count(customer_id) desc) as item_rank from mytable
group by category, item_purchased
)
select category, item_purchased, item_rank
from item_ranks
where item_rank <=3;

-- Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select subscription_status,
count(customer_id) as repeat_buyers
from mytable
where previous_purchases > 5
group by subscription_status;

-- What is the revenue contribution of each age group?
select age_group, sum(purchase_amount) from mytable
group by age_group
order by sum(purchase_amount) desc;